### 3. If You Need Card Validation
```javascript
function validateLuhn(cardNumber) {
  const digits = cardNumber.replace(/\D/g, '').split('');
  let sum = 0;
  let isEven = true;

  for (let i = digits.length - 1; i >= 0; i--) {
    let digit = parseInt(digits[i]);
    if (isEven) {
      digit *= 2;
      if (digit > 9) digit -= 9;
    }
    sum += digit;
    isEven = !isEven;
  }

  return sum % 10 === 0;
}

// Use only for validation, never log full numbers
